import json

def solve_v12(grid):
    """Output 1 if i > j OR (i==0 AND j==n-1)"""
    n = len(grid)

    result = []
    for i in range(n):
        row = []
        for j in range(n):
            if i > j or (i == 0 and j == n - 1):
                row.append(1)
            else:
                row.append(2)
        result.append(row)
    return result

demo_out_expected = [[2,2,2,1],[1,2,2,2],[1,1,2,2],[1,1,1,2]]

print("Prediction:")
for row in solve_v12([]):
    print(row)
print("\nExpected:", json.dumps(demo_out_expected))

